static boolean waitForServerReady(String host, int port, int maxAttempts, int delayMs) throws InterruptedException {
    for (int i=0;i<maxAttempts;i++) {
        try (Socket s = new Socket(host, port)) { return true; }
        catch (IOException e) { Thread.sleep(delayMs); }
    }
    return false;
}
